import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BG8d4IEm.js";const p="/assets/2016-11-14-apache.D0LnY4kW.gif",u=JSON.parse('{"title":"wamp","description":"","frontmatter":{"tags":["工具"]},"headers":[],"relativePath":"posts/2016-11-14-wamp.md","filePath":"posts/2016-11-14-wamp.md"}'),i={name:"posts/2016-11-14-wamp.md"};function n(l,e,s,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="wamp" tabindex="-1">wamp <a class="header-anchor" href="#wamp" aria-label="Permalink to &quot;wamp&quot;">​</a></h1><p><strong>wamp 的安装和配置笔记</strong></p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>wamp 是一个集成了 PHP、mysql、apache 的开发环境。</p><p><strong>注意在 wamp 下重装环境时配置文件不会变化</strong> 这会导致原来无法运行的模块依旧不能正常工作。</p><ol><li>不要随便修改配置文件。记得备份，搞清楚了再动手。</li></ol><h2 id="debug" tabindex="-1">debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;debug&quot;">​</a></h2><p>在安装 apache 是，软件运行可能会出故障解决思路如下。</p><ol><li>定位错误</li></ol><p><img src="'+p+`" alt="" loading="lazy"></p><p>若显示没有占用，请查看 apache 下 error log 的信息。 若利用上述步骤任无法定位问题，进入 wamp 下 apache 的 bin 目录。wamp 软件下路径如下 <code>\\wamp\\bin\\apache\\apache2.4.9\\bin</code>。 在该路径下打开命令行工具，执行如下语句。</p><div class="language-dos line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dos</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>   httpd.exe -e debug  //该命令会显示 apache 的加载过程</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>根据结果定位错误位置。</p><ol start="2"><li>处理错误</li></ol><ul><li><p>端口被占用</p><p>若Test Port 80 端口被占用。修改文件 apache.sysConst 。</p><pre><code>  Listen 0.0.0.0:80 改为
  Listen 0.0.0.0::8080
</code></pre></li><li><p>端口未被占用，wamp 服务为橙色</p><ol><li>左键点击 apache 图标，点击 Apache &gt; Service &gt; Install Service。</li><li>左键点击 apache 图标，点击 Apache &gt; Service &gt; Start Service</li><li>左键点击 apache 图标，点击 Put online 即可</li><li>若在执行上述步骤是出现 <code>Could not execute menu item</code>请参看如下链接<br><a href="http://stackoverflow.com/questions/10266656/could-not-execute-menu-item-internal-errorexception-when-changing-php-vers" target="_blank" rel="noreferrer">修改上线错误</a></li></ol></li><li><p>端口未被占用但是启用服务后显示 <code>Forbidden</code></p></li></ul><h2 id="配置数据库时无法重启" tabindex="-1">配置数据库时无法重启 <a class="header-anchor" href="#配置数据库时无法重启" aria-label="Permalink to &quot;配置数据库时无法重启&quot;">​</a></h2><p>修改 <code>my.ini</code> 的配置文件时注意保存为 <strong>ASCII</strong> 格式。 <a href="http://stackoverflow.com/questions/8020297/mysql-my-cnf-file-found-option-without-preceding-group" target="_blank" rel="noreferrer">第一行错误</a></p><h2 id="经验" tabindex="-1">经验 <a class="header-anchor" href="#经验" aria-label="Permalink to &quot;经验&quot;">​</a></h2><p>配置文件出错时去各分离部分查找问题。</p>`,19)])])}const g=a(i,[["render",n]]);export{u as __pageData,g as default};
